package com.kaipai.integration.ai.profileimport;
import com.fasterxml.jackson.databind.*; import com.kaipai.common.exception.BizException; import com.kaipai.model.ai.entity.AiProfileImportConfig; import com.kaipai.service.ai.profileimport.ProfileImportHttpTransport; import java.util.Map;
public class DeepSeekProfileTextExtractor { private final ProfileImportHttpTransport transport; private final ObjectMapper mapper=new ObjectMapper(); public DeepSeekProfileTextExtractor(ProfileImportHttpTransport transport){this.transport=transport;} public JsonNode extract(AiProfileImportConfig config,String apiKey,String rawText,String requestId){String response;try{response=transport.post(config.getEndpoint(),apiKey,payload(rawText,config.getModelName()));}catch(ProfileImportHttpTransport.Timeout e){throw new BizException(46006,"智能导入模型响应超时");}catch(Exception e){throw new BizException(46002,"DeepSeek 服务不可用");}try{return parse(response);}catch(Exception first){try{return parse(transport.post(config.getEndpoint(),apiKey,payload("仅修复为合法 JSON，不改变内容："+response,config.getModelName())));}catch(Exception second){throw new BizException(46007,"智能导入结果无法解析");}}} private JsonNode parse(String value)throws Exception{JsonNode node=mapper.readTree(value);if(node==null||!node.isObject())throw new Exception();return node;} private String payload(String text,String model){try{return mapper.writeValueAsString(Map.of("model",model,"messages",java.util.List.of(Map.of("role","user","content",text)),"response_format",Map.of("type","json_object")));}catch(Exception e){throw new IllegalStateException(e);}}}
